# owner: platform
import unittest

from hourglass.rounding import round_span, rounded_labels
from hourglass.models import Span


class RoundingTests(unittest.TestCase):
    def test_label_after_rounding(self):
        spans = [Span(7 * 60 + 58, 17 * 60 + 12)]
        self.assertEqual(
            rounded_labels(spans, 15),
            ["08:00-17:15 (9h 15m)"]
        )

    def test_halves_round_up(self):
        self.assertEqual(
            round_span(Span(67, 128), 15), Span(75, 135)
        )

    def test_bad_steps_raise(self):
        for step in (0, -5, 7, 45, 90):
            with self.assertRaises(ValueError):
                rounded_labels([Span(0, 60)], step)

    def test_empty_list(self):
        self.assertEqual(rounded_labels([], 5), [])
